-- PT104-S4-Q1. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT104-S4-Q1$batch09$ AND q.stimulus=$batch09$Politician: Governments should tax any harmful substance that is available to the general public at a level that the tax would discourage continued use of the substance.$batch09$ AND q.prompt=$batch09$Which one of the following is an application of the politician's principle of taxation?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT104-S4-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT104-S4-Q1$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S4-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT104-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$If a substance is harmful and available to the general public, the government should tax it at a level that discourages continued use.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Two things to check in each choice. Is the substance harmful and available to the public? And is the tax set to discourage use? The purpose matters. Raising money, helping tourism or encouraging new technology are other goals.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A tax raised on a harmful, public substance so that people use less of it.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT104-S4-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The tax goes up to raise revenue for health costs. The rule sets the tax to discourage use, and A never says use should fall.$batch09$), ($batch09$B$batch09$, $batch09$The studies say demand won't be affected, so this tax can't discourage use. That's the one effect the rule cares about.$batch09$), ($batch09$C$batch09$, $batch09$The pesticide contains a compound harmful to people, the tax is raised, and the point is to push buyers toward pesticides without it. Higher tax, less use of the harmful product. That's the rule in action.$batch09$), ($batch09$D$batch09$, $batch09$The tax isn't raised at all, and the reason is tourism. The rule never weighs tourism.$batch09$), ($batch09$E$batch09$, $batch09$The tax on a harmful product is lowered. The rule calls for a tax high enough to discourage use.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT104-S4-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
